delete from public.sections where page_id = (select id from public.pages where slug = '/industries/aerospace-aviation');
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Aerospace & Aviation","heading":"SEO for Aerospace and Aviation Suppliers","body":"Aerospace buyers search by part, standard and certification, and they qualify before they contact. The work is being findable and credible in that order. For Houston-area suppliers, local credibility supports a search process whose competitive reach is usually national.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"report","label":"How buyers search","title":"By Part and Approval","items":["Part numbers","Materials and specifications","Certifications first","Across several weeks"]},{"kind":"coverage","label":"What it rests on","title":"Findable Detail","items":["Crawlable pages","Named approvals","Published ranges"]}]}'::jsonb, 0 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"split","columns":3,"eyebrow":"Who This Is For","heading":"Suppliers This Applies To","body":"Examples of businesses that share this search pattern and buying cycle.","cards":[{"title":"Aviation Services & Hangar Operations","icon":"plane","body":"Capability, certification and location together decide who gets contacted."},{"title":"Aerospace Manufacturing & Parts Suppliers","icon":"factory","body":"Found by part number, material and specification, frequently by an engineer rather than a buyer."},{"title":"Defense & Space Contracting","icon":"shield-check","body":"Clearance, compliance and past performance are the first filters applied, before capability."}]}'::jsonb, 1 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behavior', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behavior","heading":"What Search Looks Like in Aerospace","body":"Aerospace is the clearest example of search as qualification rather than as marketing. A procurement manager comparing specifications over six weeks is not going to be moved by a headline, and an engineer searching for a part number either finds a page carrying that number or does not. Certification is often the first filter applied, before capability and long before price.\n\nThe practical consequence is that the searchable surface of a supplier''s site is usually far too small. Capabilities live in a PDF, part ranges live in a table nobody can crawl, and approvals are named on an about page rather than where they would be searched for. Fixing that is unglamorous work with an unusually direct effect, and the competition for it is national rather than local.","groups":[{"title":"Certification filters first","icon":"shield-check","body":"Approvals belong on crawlable pages, not only inside a downloadable document."},{"title":"Part numbers are queries","icon":"search","body":"If a range only exists inside a PDF or a script-driven table, it cannot be found."},{"title":"Weeks of comparison before contact","icon":"calendar","body":"The site is doing the selling during a period when nobody is talking to you."}]}'::jsonb, 2 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'fullWidthText', 'surface', '{"eyebrow":"Where to Start","heading":"This Work Sits in Traditional SEO","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth.\n\nAerospace & Aviation buyers are not searching inside a drive-time radius. The work is specification, capability and procurement language across a region or a country, so a local campaign would optimize for a map pack that the people making these decisions never open.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}'::jsonb, 3 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. In aerospace the answers start with approvals, because that is the first filter a buyer applies.","did":"The work completed that month, named task by task: capability and approval pages, part and service detail made findable, and the technical work that lets a very narrow search reach it.","why":"Why that work came first, which is usually an approval or a capability buyers filter on that the site does not state in a form search can read.","changed":"Which part, capability and approval searches moved, and what the inquiries that arrived were qualified against. Reported honestly, including the months where little moved.","next":"Next month''s priorities in order, on a procurement cycle that does not reward rushing.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Aerospace & Aviation Questions","items":[{"question":"Is search volume high enough to be worth the work?","answer":"Volume is low and value is very high, so the goal is not traffic. A narrow set of technical searches, found by the right handful of people, is what the tracked keyword set is built around."},{"question":"What about content that cannot be published?","answer":"Plenty in this sector is restricted, and none of it needs publishing. The gains usually come from making already-public capability, approvals and part information properly findable."},{"question":"Is a supplier competing locally or nationally?","answer":"Almost always nationally, which puts most aerospace suppliers in the Traditional lane. A ground services business tied to one airport is the exception, and it is a Local engagement."},{"question":"What should an aerospace supplier make searchable first?","answer":"Start with public approvals, capabilities, parts and service ranges that buyers already use to qualify suppliers. Each detail needs a crawlable home and the client''s technical approval before it becomes part of the search surface."},{"question":"How does JMC report progress for an aerospace supplier?","answer":"JMC applies League City and Houston-area context where location matters, then measures the national part, capability and approval searches that drive qualification. The monthly recap ties every movement to completed, client-approved work."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/aerospace-aviation';
